#!/usr/bin/env node
// Bakes the card's pattern tiles out of pattern.monster's data (MIT), as @gryt/owl does for eggs.
// Run after editing cardPatterns.json; `--check` fails when the generated files are stale.

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const DIR = join(dirname(fileURLToPath(import.meta.url)), "..", "src/packages/socket/src/lib/memberCard/patterns");
const list = JSON.parse(readFileSync(join(DIR, "cardPatterns.json"), "utf8"));

/** The stroke a line pattern is drawn with on the card, in CSS pixels. */
const STROKE_PX = 1.4;

const url = `https://raw.githubusercontent.com/catchspider2002/svelte-svg-patterns/${list.revision}/src/routes/_index.js`;
const source = await (await fetch(url)).text();
// The file is `const index = [...]` and nothing else, so JSON.parse rejects anything unexpected.
const body = source.replace(/^\s*const index\s*=\s*/, "").replace(/;?\s*(export default index;?)?\s*$/, "");
const upstream = new Map(JSON.parse(body).map((p) => [p.slug, p]));

const seen = new Set();
const baked = list.patterns.map((entry) => {
  if (seen.has(entry.slug)) throw new Error(`"${entry.slug}" is listed twice.`);
  seen.add(entry.slug);
  if (!/^[a-z0-9-]{1,32}$/.test(entry.slug)) throw new Error(`"${entry.slug}" is not a slug the server keeps.`);
  const p = upstream.get(entry.slug);
  if (!p) throw new Error(`pattern.monster has no "${entry.slug}" any more.`);

  // A tile with a vHeight stacks rows of one shape; two rows is one row of shapes.
  const stacked = p.vHeight > 0;
  const rows = stacked ? Math.min(2, p.colors) : p.colors;
  const layers = p.path.split("~").slice(0, stacked ? rows - 1 : Math.max(1, p.colors - 1));
  const height = stacked ? p.height - p.vHeight * (p.colors - rows) : p.height;
  const scale = entry.tile / p.width;
  const stroke = Math.round(Math.min(p.maxStroke || Infinity, STROKE_PX / scale) * 100) / 100;
  return { id: entry.slug, mode: p.mode === "stroke-join" ? "round" : p.mode, width: p.width, height, tile: entry.tile, stroke, layers };
});

const HEADER = `// Generated by scripts/card-patterns.mjs from cardPatterns.json. Do not edit.
// The tiles are pattern.monster's, under the MIT licence in LICENSE-pattern-monster.txt.
`;

const index =
  HEADER +
  `\nimport type { TileIndexEntry } from "./tileTypes";\n\n` +
  `export const TILE_INDEX: readonly TileIndexEntry[] = [\n` +
  list.patterns.map((e) => `  { id: ${JSON.stringify(e.slug)}, name: ${JSON.stringify(e.name)}, group: ${JSON.stringify(e.group)} },`).join("\n") +
  `\n];\n`;

const tiles =
  HEADER +
  `\nimport type { Tile } from "./tileTypes";\n\n` +
  `export const TILES: readonly Tile[] = [\n` +
  baked
    .map(
      (t) =>
        `  { id: ${JSON.stringify(t.id)}, mode: ${JSON.stringify(t.mode)}, width: ${t.width}, height: ${t.height}, tile: ${t.tile}, stroke: ${t.stroke}, ` +
        `layers: [${t.layers.map((d) => JSON.stringify(d)).join(", ")}] },`,
    )
    .join("\n") +
  `\n];\n`;

const files = [
  [join(DIR, "tileIndex.generated.ts"), index],
  [join(DIR, "tiles.generated.ts"), tiles],
];

if (process.argv.includes("--check")) {
  const stale = files.filter(([path, text]) => readFileSync(path, "utf8") !== text);
  if (stale.length) {
    console.error(`stale: ${stale.map(([p]) => p).join(", ")}. Run: node scripts/card-patterns.mjs`);
    process.exit(1);
  }
  console.log("card patterns up to date");
} else {
  for (const [path, text] of files) writeFileSync(path, text);
  console.log(`wrote ${baked.length} tiles, ${(tiles.length / 1024).toFixed(0)} kB of paths, ${(index.length / 1024).toFixed(0)} kB of index`);
}
